    "question": "Kalp hızı 60 atım/dk, kardiyak debisi (CO) 3000 mL/dk ve sol ventrikül diyastol sonu hacmi (EDV) 100 mL olan bir kişinin ejeksiyon fraksiyonu (EF) yüzde kaçtır?",
