    "open_answer": "%50",
    "explanation": "Doğru Seçenek: C) %50. Atım hacmi (SV) = Debi / Kalp Hızı = 3000 mL/dk / 60 vuru/dk = 50 mL. Ejeksiyon Fraksiyonu (EF) = (SV / EDV) x 100 = (50 mL / 100 mL) x 100 = %50 olarak hesaplanır.",
    "note": "Öğrenci hatırlama notundan 5 şıklı çoktan seçmeli soruya dönüştürülmüştür.",
