    "question": "Akciğer alveollerinde sürfaktanın yeterli düzeyde salgılanması fizyolojik olarak neyi azaltır ve neyi dengeler?",
    "options": [
      {
        "letter": "A",
        "text": "Sadece hava-kan bariyerinde kapiller hidrostatik basıncı düşürür."
      },
      {
        "letter": "B",
        "text": "Akciğer kompliyansını düşürür ve inspiratuar iş yükünü dengeler."
      },
      {
        "letter": "C",
        "text": "Alveoler yüzey gerilimini artırır ve elastik recoil kuvvetini yükseltir."
      },
      {
        "letter": "D",
        "text": "Alveoler yüzey gerilimini azaltır ve farklı çaplardaki alveollerin iç basınçlarını eşitler."
      },
      {
        "letter": "E",
        "text": "Küçük alveollerin büyük alveollere doğru kollaps olmasını hızlandırır."
      }
    ],
    "answer": "D",
    "open_answer": "Alveoler yüzey gerilimi azalır; farklı çaplardaki alveollerin iç basınçları eşitlenir.",
    "explanation": "Doğru Seçenek: D) Alveoler yüzey gerilimini azaltır ve farklı çaplardaki alveollerin iç basınçlarını eşitler.. Sürfaktan yüzey gerilimini düşürür ve Laplace yasasına (P=2T/r) göre küçük alveollerde daha yoğunlaşarak yüzey gerilimini daha fazla azaltır. Böylece farklı çaplardaki alveollerin iç basınçları eşitlenir ve küçük alveollerin sönmesi (atelektazi) önlenir.",
    "note": "Öğrenci hatırlama notundan 5 şıklı çoktan seçmeli soruya dönüştürülmüştür.",
