    "answer": "B",
    "open_answer": "Parietal yaprak basit yassı epiteldir. Nefritlerde (Crescentik/Hilalli glomerulonefrit) hücreleri proliferasyon gösterir. Bowman mesangium hücreleri ve podositler bazal lamina bileşenlerini salgılar. İnek Sütü Alerjisi Vakası (Hapten vs. İmmünojen)",
    "explanation": "Doğru Seçenek: B) Bowman kapsülü parietal epitel hücreleri. Kresentik glomerülonefritte glomerül kapiller duvarı hasar görünce Bowman aralığına fibrin ve inflamatuar mediyatörler sızar. Bu durum Bowman kapsülü parietal epitel hücrelerinin kontrolsüz proliferasyonuna ve makrofaj göçüne yol açarak karakteristik hilal (kresent) yapısını oluşturur.",
